 860→
 861→        let _ = handle_gap_interactive(&gap, &mut checker, &mut ui, &ctx);
 862→        assert!(!checker.cache.contains_key("redis"));
 863→        assert!(checker.cache.contains_key("ruby"));
 864→    }
