#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;

    #[test]
    fn cache_store_creation() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        assert_eq!(store.root(), temp.path());
    }

    #[test]
    fn store_and_load() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let entry = store
            .store("http:test", "template1", "template content", 3600)
            .unwrap();

        assert_eq!(entry.source_id, "http:test");
        assert_eq!(entry.template_name, "template1");

        let loaded = store.load("http:test", "template1").unwrap().unwrap();
        assert_eq!(loaded.source_id, entry.source_id);
        assert_eq!(loaded.template_name, entry.template_name);
    }

    #[test]
    fn read_content() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let entry = store
            .store("http:test", "template1", "hello world", 3600)
            .unwrap();

        let content = store.read_content(&entry).unwrap();
        assert_eq!(content, "hello world");
    }

    #[test]
    fn load_nonexistent_returns_none() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let result = store.load("http:test", "nonexistent").unwrap();
        assert!(result.is_none());
    }

    #[test]
    fn remove_entry() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template1", "content", 3600)
            .unwrap();

        let removed = store.remove("http:test", "template1").unwrap();
        assert!(removed);

        let loaded = store.load("http:test", "template1").unwrap();
        assert!(loaded.is_none());
    }

    #[test]
    fn remove_nonexistent_returns_false() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let removed = store.remove("http:test", "nonexistent").unwrap();
        assert!(!removed);
    }

    #[test]
    fn list_entries() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template1", "content1", 3600)
            .unwrap();
        store
            .store("http:test", "template2", "content2", 3600)
            .unwrap();

        let entries = store.list().unwrap();
        assert_eq!(entries.len(), 2);
    }

    #[test]
    fn clear_cache() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template1", "content1", 3600)
            .unwrap();
        store
            .store("http:test", "template2", "content2", 3600)
            .unwrap();

        let cleared = store.clear().unwrap();
        assert_eq!(cleared, 2);

        let entries = store.list().unwrap();
        assert!(entries.is_empty());
    }

    #[test]
    fn total_size_calculation() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store.store("http:test", "t1", "12345", 3600).unwrap(); // 5 bytes
        store.store("http:test", "t2", "1234567890", 3600).unwrap(); // 10 bytes

        let total = store.total_size().unwrap();
        assert_eq!(total, 15);
    }

    #[test]
    fn content_path_is_deterministic() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let path1 = store.content_path("http:test", "template");
        let path2 = store.content_path("http:test", "template");

        assert_eq!(path1, path2);
    }

    #[test]
    fn different_entries_have_different_paths() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let path1 = store.content_path("http:test", "template1");
        let path2 = store.content_path("http:test", "template2");

        assert_ne!(path1, path2);
    }

    #[test]
    fn concurrent_stores_produce_consistent_entries() {
        use std::sync::{Arc, Barrier};
        use std::thread;

        for _ in 0..5 {
            let temp = TempDir::new().unwrap();
            let store = Arc::new(CacheStore::new(temp.path()));
            let num_threads: usize = 20;
            let barrier = Arc::new(Barrier::new(num_threads));

            let handles: Vec<_> = (0..num_threads)
                .map(|i| {
                    let store = Arc::clone(&store);
                    let barrier = Arc::clone(&barrier);
                    thread::spawn(move || {
                        barrier.wait();
                        let ch = (b'a' + (i as u8 % 26)) as char;
                        let content: String =
                            std::iter::repeat(ch).take((i + 1) * 500).collect();
                        store
                            .store("http:test", "template", &content, 3600)
                            .unwrap();
                    })
                })
                .collect();

            for handle in handles {
                handle.join().unwrap();
            }

            let entry = store.load("http:test", "template").unwrap().unwrap();
            let content = store.read_content(&entry).unwrap();

            assert_eq!(
                entry.metadata.size_bytes,
                content.len() as u64,
                "metadata size {} != content size {}",
                entry.metadata.size_bytes,
                content.len()
            );

            let first = content.chars().next().unwrap();
            assert!(
                content.chars().all(|c| c == first),
                "content contains mixed characters from different writers"
            );
        }
    }

    #[test]
    fn concurrent_reads_during_writes_never_observe_corruption() {
        use std::sync::atomic::{AtomicBool, Ordering};
        use std::sync::Arc;
        use std::thread;

        let temp = TempDir::new().unwrap();
        let store = Arc::new(CacheStore::new(temp.path()));

        store
            .store("http:test", "t", "seed-content", 3600)
            .unwrap();

        let stop = Arc::new(AtomicBool::new(false));
        let mut reader_handles = Vec::new();

        for _ in 0..5 {
            let store = Arc::clone(&store);
            let stop = Arc::clone(&stop);
            reader_handles.push(thread::spawn(move || {
                while !stop.load(Ordering::Relaxed) {
                    match store.load("http:test", "t") {
                        Ok(Some(entry)) => {
                            if let Ok(content) = store.read_content(&entry) {
                                assert_eq!(
                                    entry.metadata.size_bytes,
                                    content.len() as u64,
                                    "reader saw inconsistent metadata/content"
                                );
                            }
                        }
                        Ok(None) => {}
                        Err(_) => {
                            panic!("reader got corrupted metadata (invalid JSON)");
                        }
                    }
                    thread::yield_now();
                }
            }));
        }

        let writer_handles: Vec<_> = (0..10)
            .map(|i| {
                let store = Arc::clone(&store);
                thread::spawn(move || {
                    let ch = (b'a' + (i as u8 % 26)) as char;
                    let content: String =
                        std::iter::repeat(ch).take((i + 1) * 500).collect();
                    for _ in 0..50 {
                        store.store("http:test", "t", &content, 3600).unwrap();
                        thread::yield_now();
                    }
                })
            })
            .collect();

        for h in writer_handles {
            h.join().unwrap();
        }

        stop.store(true, Ordering::Relaxed);

        for h in reader_handles {
            h.join().unwrap();
        }
    }
}

